// Research engine. Signals never use the return period's closing price.
const fallbackClose=[100,101,100,102,103,102,104,103,105,107,106,108,110,109,112,114,113,115,118,120,117,114,116,112,110,113,111,115,116,118,117,121,120,123,119,117,120,124,122,126];
const fallbackRows=fallbackClose.map((close,i)=>({date:`观察点 ${i+1}`,close,open:i?fallbackClose[i-1]:100,volume:1000+(i*137)%700}));
const supplied=typeof window!=='undefined'?window.PANDA_DATA:null;
const dataset=supplied&&Array.isArray(supplied.rows)&&supplied.rows.length>=16?supplied:{source:'synthetic_demo',symbol:'合成资产',adjustment:'不适用',rows:fallbackRows};
const rows=dataset.rows,prices=rows.map(r=>r.close),split=Math.max(10,Math.min(20,Math.floor(rows.length*2/3))),realData=dataset.source==='Panda Data';
const dataLabel=realData?'Panda Data · 真实历史样本':'演示模式 · 合成样本';
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function qualityReport(input=rows){const dates=input.map(r=>r.date),missing=input.filter(r=>['open','close','volume'].some(k=>r[k]===null||r[k]===undefined||!Number.isFinite(r[k]))).length,invalid=input.filter(r=>r.open<=0||r.close<=0||r.volume<0).length;return {count:input.length,missing,invalid,duplicates:dates.length-new Set(dates).size}}
function research(n,input=rows,cut=split){if(n<2||n>cut-1||input.length<=cut+1)throw Error('Insufficient sample');let equity=1,peak=1,dd=0,position=0,trades=0,path=[1],signals=[];for(let i=cut;i<input.length-1;i++){const mean=input.slice(i-1-n,i-1).reduce((a,r)=>a+r.close,0)/n;const next=input[i-1].close>mean?1:0;const change=Math.abs(next-position);equity*=1-change*.001;equity*=1+next*(input[i+1].open/input[i].open-1);trades+=change;position=next;peak=Math.max(peak,equity);dd=Math.max(dd,1-equity/peak);path.push(equity);signals.push({signalDate:input[i-1].date,executionDate:input[i].date,position:next})}if(position){equity*=.999;trades++;path[path.length-1]=equity;dd=Math.max(dd,1-equity/peak)}let base=.999,basePeak=1,baseDD=1-base;const benchmark=[1];for(let i=cut;i<input.length-1;i++){base*=input[i+1].open/input[i].open;basePeak=Math.max(basePeak,base);baseDD=Math.max(baseDD,1-base/basePeak);benchmark.push(base)}base*=.999;benchmark[benchmark.length-1]=base;baseDD=Math.max(baseDD,1-base/basePeak);return{ret:(equity-1)*100,dd:dd*100,trades,path,benchmark,baseReturn:(base-1)*100,baseDD:baseDD*100,signals,periods:input.length-cut-1}}
function compute(n){return research(n)}
function volumeClue(){let recent=rows.slice(split-3,split).reduce((a,r)=>a+r.volume,0)/3,prior=rows.slice(0,split-3).reduce((a,r)=>a+r.volume,0)/(split-3);return prior>0?`截至决策时点，最近 3 日均量是此前 ${split-3} 日均量的 ${(recent/prior).toFixed(2)} 倍。量能变化本身不能证明下一步涨跌。`:'此前成交量不足，暂不计算量比。'}
function evidenceHeadline(){let change=(prices[split-1]/prices[0]-1)*100;return `可见区间价格变化 ${change>=0?'+':''}${change.toFixed(2)}% · 下一步仍未知`}
